INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.project/fuzz', 'did:plc:demojun0001', 'fuzz', 'electronics', 'Fuzz pedal from a 1970s schematic', 'A two-transistor fuzz built on stripboard, then moved to a real enclosure. Every mistake is in here.', 'in-progress', NULL, '2026-03-03T19:12:00.000Z', 1772565120000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-01', 'did:plc:demojun0001', 'fuzz-01', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'Schematic and a parts order', 'Found the schematic in an old magazine scan. Redrew it so I could read it, and ordered parts for two builds in case I fry the first.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-34-fuz1a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Hand-redrawn fuzz schematic on squared paper, two transistors circled"}]', '[{"url": "https://example.org/fuzz-schematic-redraw", "title": "My redrawn schematic (PDF)"}]', '[{"item": "2N3904 transistor", "quantity": "4", "note": "two spares"}, {"item": "100k audio pot", "quantity": "2"}, {"item": "Hammond 1590B enclosure", "quantity": "1"}, {"item": "10k resistor", "quantity": "6"}]', '2026-03-03T19:12:00.000Z', 1772565120000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-02', 'did:plc:demojun0001', 'fuzz-02', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'Breadboard works, barely', 'It fuzzes. It also hums. The hum goes away when I touch the ground rail, so the ground is the first suspect.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-43-fuz2a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Breadboard with two transistors, jumper wires and a 9 V battery clip"}, {"image": {"$type": "blob", "ref": {"$link": "ph-11-fuz2b"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Multimeter probe on the breadboard ground rail"}]', NULL, NULL, '2026-03-21T20:40:00.000Z', 1774125600000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-03', 'did:plc:demojun0001', 'fuzz-03', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'Stripboard layout', 'Cut the tracks with a drill bit by hand. Checked every cut with the meter, found two I missed.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-32-fuz3a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Stripboard from above with cut tracks marked in red pen"}]', NULL, '[{"item": "Stripboard", "quantity": "1", "note": "95 x 64 mm"}]', '2026-04-12T18:05:00.000Z', 1776017100000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-04', 'did:plc:demojun0001', 'fuzz-04', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'The hum was the jack', 'A lifted ground on the input jack. Resoldered it and the noise floor dropped to almost nothing.
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-05', 'did:plc:demojun0001', 'fuzz-05', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'Drilling the enclosure', 'Printed a template, centre-punched, drilled small first. The footswitch hole is 1 mm off and you can see it.', '[{"image": {"$type": "blob", "ref": {"$link": "bafkreidemobroken0001"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Aluminium enclosure with five drilled holes"}]', NULL, NULL, '2026-08-17T16:00:00.000Z', 1786982400000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/fuzz-06', 'did:plc:demojun0001', 'fuzz-06', 'at://did:plc:demojun0001/pub.workbench.project/fuzz', 'First gig test', 'Played it through a friend''s amp at rehearsal. Too much bass at full gain, so the input capacitor gets smaller next.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-32-fuz6a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Finished pedal on a rehearsal room floor next to a guitar cable"}, {"image": {"$type": "blob", "ref": {"$link": "ph-34-fuz6b"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Pedal in a hand, footswitch facing the camera"}, {"image": {"$type": "blob", "ref": {"$link": "ph-11-fuz6c"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Close-up of the gain and volume knobs"}]', NULL, NULL, '2026-10-29T19:30:00.000Z', 1793302200000, 0);
INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.project/nightbus', 'did:plc:demomara0001', 'nightbus', 'music-production', 'Night Bus', 'From a voice memo recorded on the last bus home to a finished four-track EP. Every version is kept.', 'in-progress', NULL, '2026-03-03T23:40:00.000Z', 1772581200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.update/nightbus-01', 'did:plc:demomara0001', 'nightbus-01', 'at://did:plc:demomara0001/pub.workbench.project/nightbus', 'Voice memo', 'Humming over the engine noise on the 23:40 bus. Kept the engine in.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-11-nig1a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Phone screen showing a 48-second voice memo waveform"}]', NULL, NULL, '2026-03-03T23:40:00.000Z', 1772581200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.update/nightbus-02', 'did:plc:demomara0001', 'nightbus-02', 'at://did:plc:demomara0001/pub.workbench.project/nightbus', 'Demo', 'Drum machine, one synth, the memo chopped into a loop. Rough, but the chord change at 1:10 is the song.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-43-nig2a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Drum machine and a small synth on a desk, cables everywhere"}]', NULL, NULL, '2026-04-18T14:00:00.000Z', 1776520800000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.update/nightbus-03', 'did:plc:demomara0001', 'nightbus-03', 'at://did:plc:demomara0001/pub.workbench.project/nightbus', 'Arrangement', 'Cut the intro from 32 bars to 8. The bridge now drops everything except the bass and the bus recording.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-32-nig3a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Arrangement view with six tracks, the intro cut to eight bars"}]', NULL, NULL, '2026-09-02T11:30:00.000Z', 1788348600000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.update/nightbus-04', 'did:plc:demomara0001', 'nightbus-04', 'at://did:plc:demomara0001/pub.workbench.project/nightbus', 'Mix, version 3', 'Big on headphones, muddy in the car. Too much happening around 250 Hz.', NULL, NULL, NULL, '2026-10-04T10:15:00.000Z', 1791108900000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.update/nightbus-05', 'did:plc:demomara0001', 'nightbus-05', 'at://did:plc:demomara0001/pub.workbench.project/nightbus', 'Mix, version 4', 'Pulled the pads down 3 dB and put the vocal back on top. Listened in the car twice before posting this one.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-32-nig5a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Mixer plugin with the pad bus pulled down 3 dB"}, {"image": {"$type": "blob", "ref": {"$link": "ph-43-nig5b"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Car dashboard with a phone playing the mix"}]', NULL, NULL, '2026-10-21T21:42:00.000Z', 1792618920000, 0);
INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.project/celadon', 'did:plc:demoines0001', 'celadon', 'ceramics', 'Glaze test series: celadon', 'Twelve test tiles, one base glaze, iron oxide from 0.5 to 3 percent. Fired to cone 10 reduction.', 'finished', NULL, '2026-02-08T09:00:00.000Z', 1770541200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-01', 'did:plc:demoines0001', 'celadon-01', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Mixing the base', 'Weighed out six 100 g batches. Sieved twice through 80 mesh.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-11-cel1a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Six labelled glaze buckets on a scale"}]', NULL, '[{"item": "Potash feldspar", "quantity": "40 g"}, {"item": "Silica", "quantity": "30 g"}, {"item": "Whiting", "quantity": "20 g"}, {"item": "EPK kaolin", "quantity": "10 g"}, {"item": "Red iron oxide", "quantity": "0.5-3 g", "note": "per batch"}]', '2026-02-08T09:00:00.000Z', 1770541200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-02', 'did:plc:demoines0001', 'celadon-02', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Tiles thrown and trimmed', 'Twelve tiles from one pull, each stamped with its batch number on the back.', NULL, NULL, NULL, '2026-02-15T13:20:00.000Z', 1771161600000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-03', 'did:plc:demoines0001', 'celadon-03', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Bisque out', 'No cracks. Two tiles warped a little. Kept them in anyway.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-43-cel3a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Bisque-fired tiles on a kiln shelf, two slightly warped"}]', NULL, NULL, '2026-03-01T17:45:00.000Z', 1772387100000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-04', 'did:plc:demoines0001', 'celadon-04', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Dipped', 'Three-second dips, then a second dip on the bottom half of each tile to see the thickness change.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-34-cel4a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Hand dipping a tile into a bucket of glaze"}]', NULL, NULL, '2026-03-09T10:00:00.000Z', 1773050400000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-05', 'did:plc:demoines0001', 'celadon-05', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Glaze fire', 'Reduction started at cone 010. Cone 10 down at the top, 9 at the bottom.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-34-cel5a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Cone pack after firing, cone 10 fully bent"}]', NULL, NULL, '2026-03-16T08:30:00.000Z', 1773649800000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-06', 'did:plc:demoines0001', 'celadon-06', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Results', '1 percent is the blue-green I wanted. Above 2 percent it goes olive and then honey brown.', NULL, NULL, NULL, '2026-03-18T12:00:00.000Z', 1773835200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.update/celadon-07', 'did:plc:demoines0001', 'celadon-07', 'at://did:plc:demoines0001/pub.workbench.project/celadon', 'Chosen recipe', 'Going with 1.25 percent on porcelain. Recipe card is in the last photo of the series.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-11-cel7a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Recipe card with the chosen 1.25 percent iron celadon"}]', NULL, NULL, '2026-04-02T15:00:00.000Z', 1775142000000, 0);
INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.project/bench', 'did:plc:demosam0001', 'bench', 'woodworking', 'Workbench with a leg vise, built from reclaimed oak beams and a lot of patience over one winter', 'Roubo-style bench, 2 m long. The beams came from a barn roof and were full of nails.', 'in-progress', NULL, '2025-12-06T10:00:00.000Z', 1765015200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.update/bench-01', 'did:plc:demosam0001', 'bench-01', 'at://did:plc:demosam0001/pub.workbench.project/bench', 'Beams home', 'Six oak beams, roughly 4 m each. Found 41 nails with the detector so far.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-32-ben1a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Six oak beams stacked on trestles in a driveway"}]', NULL, NULL, '2025-12-06T10:00:00.000Z', 1765015200000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.update/bench-02', 'did:plc:demosam0001', 'bench-02', 'at://did:plc:demosam0001/pub.workbench.project/bench', 'Flattening the top', 'Hand planes only. One face flat enough to glue up after three weekends.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-43-ben2a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Jack plane on the bench top with curled shavings"}, {"image": {"$type": "blob", "ref": {"$link": "ph-32-ben2b"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Winding sticks across the flattened top"}]', NULL, NULL, '2026-01-24T14:30:00.000Z', 1769265000000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.update/bench-03', 'did:plc:demosam0001', 'bench-03', 'at://did:plc:demosam0001/pub.workbench.project/bench', 'Leg vise chop', 'Cut the chop from the best offcut. The parallel guide is a scrap of beech.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-34-ben3a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Leg vise chop clamped upright, guide of beech below"}]', NULL, '[{"item": "Vise screw, 1 in", "quantity": "1"}, {"item": "Beech offcut", "quantity": "1"}]', '2026-06-14T09:45:00.000Z', 1781430300000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.update/bench-04', 'did:plc:demosam0001', 'bench-04', 'at://did:plc:demosam0001/pub.workbench.project/bench', 'Drawbore joints', 'Pegs from riven oak. The first one split, the next five went in tight.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-11-ben4a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Riven oak pegs lined up next to a drawbored joint"}]', NULL, NULL, '2026-11-02T16:20:00.000Z', 1793636400000, 0);
INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoyael0001/pub.workbench.project/amp', 'did:plc:demoyael0001', 'amp', 'electronics', 'Small tube amp', 'Five watts, one EL84, built into a cigar box.', 'paused', NULL, '2026-05-05T18:00:00.000Z', 1778004000000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoyael0001/pub.workbench.update/amp-01', 'did:plc:demoyael0001', 'amp-01', 'at://did:plc:demoyael0001/pub.workbench.project/amp', 'Planning the layout', 'Drew the chassis layout on graph paper: power transformer at the back, the EL84 in the middle, input jack as far from the mains as the box allows. Waiting for the output transformer.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-34-amp1a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Graph paper layout of a one-tube amplifier"}]', NULL, NULL, '2026-05-05T18:00:00.000Z', 1778004000000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoyael0001/pub.workbench.update/amp-02', 'did:plc:demoyael0001', 'amp-02', 'at://did:plc:demoyael0001/pub.workbench.project/amp', 'Paused', 'The transformer is back-ordered until next year. Parking this project.', NULL, NULL, NULL, '2026-06-20T19:00:00.000Z', 1781982000000, 0);
INSERT INTO projects (uri, did, rkey, topic_slug, title, summary, status, cover, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.project/psu', 'did:plc:demojun0001', 'psu', 'electronics', 'Bench power supply', 'Adjustable 0-15 V from an old laptop brick and a buck module.', 'finished', NULL, '2025-11-10T20:00:00.000Z', 1762804800000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/psu-01', 'did:plc:demojun0001', 'psu-01', 'at://did:plc:demojun0001/pub.workbench.project/psu', 'Parts on the desk', 'Laptop brick, buck converter, a panel meter and a box.', NULL, NULL, NULL, '2025-11-10T20:00:00.000Z', 1762804800000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/psu-02', 'did:plc:demojun0001', 'psu-02', 'at://did:plc:demojun0001/pub.workbench.project/psu', 'Wired and boxed', 'Current limit works. The meter reads 0.1 V high, close enough.', '[{"image": {"$type": "blob", "ref": {"$link": "ph-43-psu2a"}, "mimeType": "image/jpeg", "size": 184320}, "alt": "Bench power supply in a black box with a red panel meter"}]', NULL, NULL, '2025-11-22T19:30:00.000Z', 1763839800000, 0);
INSERT INTO updates (uri, did, rkey, project_uri, heading, body, images, links, parts, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.update/psu-03', 'did:plc:demojun0001', 'psu-03', 'at://did:plc:demojun0001/pub.workbench.project/psu', 'Done', 'Used it to power the fuzz breadboard all spring.', NULL, NULL, NULL, '2025-12-01T18:00:00.000Z', 1764612000000, 0);
INSERT INTO replies (uri, did, rkey, subject_uri, body, created_at, indexed_at, hidden) VALUES ('at://did:plc:demomara0001/pub.workbench.reply/r1', 'did:plc:demomara0001', 'r1', 'at://did:plc:demojun0001/pub.workbench.update/fuzz-06', 'A smaller input cap worked for mine too. Try 10 nF first.', '2026-10-30T08:00:00.000Z', 1793347200000, 0);
INSERT INTO replies (uri, did, rkey, subject_uri, body, created_at, indexed_at, hidden) VALUES ('at://did:plc:demojun0001/pub.workbench.reply/r2', 'did:plc:demojun0001', 'r2', 'at://did:plc:demomara0001/pub.workbench.reply/r1', 'Will do, thanks. Ordering a few values.', '2026-10-30T09:12:00.000Z', 1793351520000, 0);
INSERT INTO replies (uri, did, rkey, subject_uri, body, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.reply/r3', 'did:plc:demoines0001', 'r3', 'at://did:plc:demomara0001/pub.workbench.update/nightbus-05', 'The engine hum under the bridge is the best part. Keep it.', '2026-10-22T07:30:00.000Z', 1792654200000, 0);
INSERT INTO replies (uri, did, rkey, subject_uri, body, created_at, indexed_at, hidden) VALUES ('at://did:plc:demosam0001/pub.workbench.reply/r4', 'did:plc:demosam0001', 'r4', 'at://did:plc:demoines0001/pub.workbench.update/celadon-06', 'The 1 percent tile is lovely. What clay body?', '2026-03-19T18:00:00.000Z', 1773943200000, 0);
INSERT INTO replies (uri, did, rkey, subject_uri, body, created_at, indexed_at, hidden) VALUES ('at://did:plc:demoines0001/pub.workbench.reply/r5', 'did:plc:demoines0001', 'r5', 'at://did:plc:demosam0001/pub.workbench.reply/r4', 'Grolleg porcelain, nothing special.', '2026-03-19T20:10:00.000Z', 1773951000000, 0);
